// 临时验证脚本（绝不提交）：验证 bug 6281 页面在“不支持 :has()”内核下的滚动回退
import { chromium } from 'playwright'

const BASE = 'http://127.0.0.1:8098'
// 楼幢变更详情（编辑态，与 bug 截图一致）
const URL = `${BASE}/#/projectmanage/building/buildingChange/2117803609552965634?formMode=edit`

function log(s) { console.log(s) }
let pass = 0, fail = 0
function assert(name, cond, extra = '') {
  if (cond) { pass++; log(`  PASS  ${name} ${extra}`) }
  else { fail++; log(`  FAIL  ${name} ${extra}`) }
}

const browser = await chromium.launch()
try {
  // ---------- 现代内核（真实 :has() 支持） ----------
  log('== A. 现代内核 ==')
  {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1034 } })
    const page = await ctx.newPage()
    await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
    await page.goto(URL, { waitUntil: 'networkidle' }).catch(() => {})
    await page.waitForTimeout(1500)
    const hasClass = await page.evaluate(() => document.documentElement.classList.contains('no-has-support'))
    assert('A1 现代内核 html 无 no-has-support', !hasClass)
    const info = await page.evaluate(() => {
      const dc = document.querySelector('.detail-container')
      if (!dc) return null
      const cs = getComputedStyle(dc)
      return { overflowY: cs.overflowY, hasTabs: !!dc.querySelector(':scope > .zs-tabs') }
    })
    log('  modern detail-container: ' + JSON.stringify(info))
    await ctx.close()
  }

  // ---------- 模拟老内核（stub CSS.supports 拒绝 :has） ----------
  log('== B. 老内核（stub :has 不支持） ==')
  {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1034 } })
    const page = await ctx.newPage()
    await page.addInitScript(() => {
      const orig = CSS.supports.bind(CSS)
      CSS.supports = function (prop, value) {
        const s = String(prop || '') + ' ' + String(value || '')
        if (/selector\s*\(\s*:has/i.test(s) || /:has\(/.test(s)) return false
        return orig(prop, value)
      }
    })
    await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' })
    await page.goto(URL, { waitUntil: 'networkidle' }).catch(() => {})
    await page.waitForTimeout(1500)
    const hasClass = await page.evaluate(() => document.documentElement.classList.contains('no-has-support'))
    assert('B1 老内核 html 打上 no-has-support', hasClass)
    const info = await page.evaluate(() => {
      const dc = document.querySelector('.detail-container')
      if (!dc) return null
      const cs = getComputedStyle(dc)
      const dfc = dc.querySelector(':scope > .detail-from-container')
      const tabs = dc.querySelector(':scope > .zs-tabs')
      return {
        overflowY: cs.overflowY,
        overflowX: cs.overflowX,
        scrollbarGutter: cs.scrollbarGutter,
        hasTabs: !!tabs,
