// 临时离线验证（不提交）：证明 html.no-has-support 回退对「detail-container > detail-from-container + zs-tabs(type=card)」形态生效
import { chromium } from 'playwright'
import fs from 'fs'
import path from 'path'

const DIST = 'D:/repository/szfc-v3-wt-bug6281-placeholder'
const ROOT = 'D:/repository/苏州市房地产监测V3/dist'
// 找含 no-has-support 的 css
const assets = fs.readdirSync(path.join(ROOT, 'assets')).filter(f => f.endsWith('.css'))
let cssFile = null
for (const f of assets) {
  const c = fs.readFileSync(path.join(ROOT, 'assets', f), 'utf8')
  if (c.includes('no-has-support')) { cssFile = path.join(ROOT, 'assets', f); break }
}
if (!cssFile) { console.error('NO CSS WITH no-has-support'); process.exit(2) }
console.log('using css:', path.basename(cssFile), Math.round(fs.statSync(cssFile).size/1024)+'KB')
const css = fs.readFileSync(cssFile, 'utf8')

// 同构 DOM：changeDetail.vue 结构（detail-container > detail-from-container + zs-tabs.tabs.zs-tabs.tabs--card > tabs-content）
const dom = (withClass) => `<!doctype html><html class="${withClass ? 'no-has-support' : ''}"><head><style>${css}</style>
<style>html,body{margin:0;height:100%} #app-main{height:100%;display:flex;flex-direction:column}</style></head>
<body><div id="app-main" class="app-main">
  <div class="detail-container">
    <div class="detail-from-container"><div style="height:700px;background:#eef">FORM 基本信息 700px</div></div>
    <div class="zs-tabs tabs tabs--card">
      <div class="tabs-bar">单元信息 | 房屋信息</div>
      <div class="tabs-content">
        <div style="height:500px;background:#fee">底部 UNIT/HOUSE 表格 500px</div>
      </div>
    </div>
  </div>
</div></body></html>`

const browser = await chromium.launch()
let pass = 0, fail = 0
const A=(n,c,x='')=>{ if(c){pass++;console.log('  PASS',n,x)}else{fail++;console.log('  FAIL',n,x)} }

async function measure(html) {
  const page = await browser.newPage({ viewport: { width: 1400, height: 600 } })
  await page.setContent(html, { waitUntil: 'load' })
  await page.waitForTimeout(100)
  const r = await page.evaluate(() => {
    const dc = document.querySelector('.detail-container')
    const dfc = document.querySelector('.detail-from-container')
    const tabs = document.querySelector('.zs-tabs')
    const tc = document.querySelector('.tabs-content')
    const g = el => el ? getComputedStyle(el) : null
    const cs = g(dc), fs = g(dfc), ts = g(tabs), tcs = g(tc)
    return {
      dcOverflowY: cs.overflowY, dcOverflowX: cs.overflowX, gutter: cs.scrollbarGutter,
      dcScrollH: dc.scrollHeight, dcClientH: dc.clientHeight,
      dfcFlex: `${fs.flexGrow}/${fs.flexShrink}/${fs.flexBasis}`, dfcOverflow: fs.overflow,
      tabsFlex: ts.flex, tabsOverflow: ts.overflow,
      tcFlex: tcs.flex, tcOverflow: tcs.overflow, tcAlign: tcs.alignItems,
    }
  })
  await page.close()
  return r
}

try {
  console.log('== 无标记（现代内核 / 已支持 :has）==')
  const modern = await measure(dom(false))
  console.log('  ', JSON.stringify(modern))
  A('M1 无 no-has-support 类', true)

  console.log('== 有标记 html.no-has-support（老内核回退）==')
  const legacy = await measure(dom(true))
  console.log('  ', JSON.stringify(legacy))
  A('L1 detail-container overflow-y=auto（整页滚动）', legacy.dcOverflowY === 'auto', legacy.dcOverflowY)
  A('L2 detail-container overflow-x=hidden', legacy.dcOverflowX === 'hidden', legacy.dcOverflowX)
  A('L3 scrollbar-gutter=stable', legacy.gutter === 'stable', legacy.gutter)
