function stripHasRules(s){
  let out='', i=0
  while(i<s.length){
    const brace=s.indexOf('{',i)
    if(brace<0){ out+=s.slice(i); break }
    const sel=s.slice(i,brace)
    // 找配对 } 同层
    let depth=1, j=brace+1
    while(j<s.length && depth>0){ if(s[j]==='{')depth++; else if(s[j]==='}')depth--; j++ }
    const rule = s.slice(i,j)
    if(sel.includes(':has(') && !sel.includes('no-has-support')){
      // 丢弃：但保留其中的 @media 等? 简化直接丢
    } else {
      out+=rule
    }
    i=j
  }
  return out
}
